import { useEffect, useState } from 'react';

const Team = () => {
  const [dashboard, setDashboard] = useState<React.ReactNode>(null);
  useEffect(() => {
    // 嵌套链第二层：team -> Dashboard -> Metrics
    import('../../components/Dashboard').then((m) => setDashboard(m.default()));
  }, []);
  return (
    <main>
      <h1>team</h1>
      {dashboard}
    </main>
  );
};
export default Team;
